entries[153031] = { ["name"] = "Glyphe 'Lichtbrut'", ["text"] = "Klassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in eine Lichtbrut. Exklusiv mit: Glyphe 'Sha' Glyphe 'Leerenekel'\nVerkaufspreis:" }
entries[153032] = { ["name"] = "Technik: Glyphe 'Lichtbrut'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Lichtbrut' schreibt.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nBenötigt Armee des Lichts\n- Freundlich\nVerkaufspreis:\nGlyphe 'Lichtbrut'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in eine Lichtbrut. Exklusiv mit: Glyphe 'Sha' Glyphe 'Leerenekel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[153033] = { ["name"] = "Glyphe 'Leerenekel'", ["text"] = "Klassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in ein Leerenekel. Exklusiv mit: Glyphe 'Sha' Glyphe 'Lichtbrut'\nVerkaufspreis:" }
entries[153034] = { ["name"] = "Technik: Glyphe 'Leerenekel'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Leerenekel' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Leerenekel'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in ein Leerenekel. Exklusiv mit: Glyphe 'Sha' Glyphe 'Lichtbrut'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[153036] = { ["name"] = "Glyphe 'Dunkle Absolution'", ["text"] = "Klassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Sühne' wird vom Schatten beeinflusst.\nVerkaufspreis:" }
entries[153037] = { ["name"] = "Technik: Glyphe 'Dunkle Absolution'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Dunkle Absolution' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Dunkle Absolution'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Sühne' wird vom Schatten beeinflusst.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[153038] = { ["name"] = "Krugas vergiftete Klaue", ["text"] = "Questgegenstand\n\"Die Klingen sind mit einem schnell wirkenden Gift überzogen. Schneidet Euch nicht!\"" }
entries[153039] = { ["name"] = "Kristalllagerfeuer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Entzündet ein Lagerfeuer aus Kristallen, das Euch das Kochen gestattet. (5 Min Abklingzeit)\nBenötigt Der Argusvorstoß\n- Wohlwollend\n\"Diese exothermen Kristalle strahlen Wärme bei minimaler Rauchbildung ab, damit die Lager der Krokul verborgen bleiben.\"\nVerkaufspreis:" }
entries[153040] = { ["name"] = "Teufelsklauenmarsuul", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[153041] = { ["name"] = "Karghufruinprescher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Karghufruinprescher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Armee des Lichts konnte nicht alle heimischen Spezies auf Argus retten. Unzählige gingen im Chaos verloren.\"\nErfolg:\n...und um Manabrötchen zu essen.\nKategorie:\nLegion" }
entries[153042] = { ["name"] = "Glorreicher Teufelszermalmer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren glorreichen Teufelszermalmer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\"Nachdem Alleria und Turalyon geschildert hatten, wie nützlich die langjährigen Begleittiere der Draenei sind, zog die Armee des Lichts mehrere davon zur Ausbildung heran.\"\nBeute von:\nLeuchtende Feldkiste" }
