entries[153113] = { ["name"] = "Seelenstein eines Dämons", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Zermalmt den Stein, tötet den Dämon dauerhaft und erhöht den Ruf bei den Fraktionen der Verheerten Inseln und auf Argus um 1000.\n\nKann nur auf Argus genutzt werden." }
entries[153114] = { ["name"] = "Nathrezimfoliant der Manipulation", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lest die Seiten, um etwas über subtile Arten zu erfahren, die Euch Umstehenden zu beeinflussen. Erhöht den Rufgewinn bei den Fraktionen der Verheerten Inseln 2 Stunden lang um 200%.\n\nKann über Stufe 49 nicht eingesetzt werden." }
entries[153115] = { ["name"] = "Sichel des Zerrütters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n9 - 17 Schaden Geschwindigkeit 3.60\n(3.6 Schaden pro Sekunde)\n+5 [Beweglichkeit oder Stärke]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
