entries[153123] = { ["name"] = "Gesprungener Kontrolledelstein für den Radinax", ["text"] = "Einzigartig\nBenutzen: Übernehmt zeitweise die Kontrolle über den Radinax, ein unaufhaltsames Gefährt. Cowabunga! (3 Sek. Abklingzeit)\n3 Aufladungen" }
entries[153124] = { ["name"] = "Pfieser Pfeiler", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt einen Geschützturm zum Einsatz, der in der Lage ist, Kleintiere in der Nähe auszumerzen. (1 Stunde Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar." }
entries[153125] = { ["name"] = "Lichtüberrest", ["text"] = "Questgegenstand\n\"Fühlt sich ungewöhnlich weich an und weist glitzernde gelbe und goldene Flecken auf.\"" }
entries[153126] = { ["name"] = "Mikroartilleriesteuerung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert eine Teufelsknallmikroartillerie. (1 Stunde Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:" }
entries[153127] = { ["name"] = "Würfel der Entdeckung", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt Euch beim Plündern von Gegnern manchmal Artefaktmachtgegenstände.\n\nFunktioniert nicht über Stufe 49. (Procchance: 10%, 5Min. Abklingzeit) (30 Sek. Abklingzeit)\n\"Wird von Wyrmzungen der Legion verwendet, um versteckte Artefakte zu finden.\"\nVerkaufspreis:" }
entries[153130] = { ["name"] = "Ausbildungsamulett der Man'ari", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nHals\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 14.\nErhöht Eure Tempowertung um + 14.\nBenutzen: Opfert 10% Gesundheit, um die Bewegungsgeschwindigkeit 10 Sek. lang um 40% zu erhöhen. (5 Min Abklingzeit)\n29 ( 29)\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nMission der Legionsordenshalle:\nAngriff auf die Teufelsfeuerwaffenkammer" }
entries[153131] = { ["name"] = "Schriftrolle der ewigen Rückkehr", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Bettet den Geist eines Loas zur Ruhe... vermeintlich. (1 Min Abklingzeit)" }
