entries[153171] = { ["name"] = "Donnerkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Gibt eine wohlklingende Melodie ab, wenn man dagegenschlägt.\"\nVerkaufspreis:" }
