entries[153174] = { ["name"] = "Zaumzeug des tapferen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGestattet es, dass beim Einsatz von 'Göttliches Ross' dieses zu Eurem tapferen Streitross wird. Exklusiv mit: Glyphe 'Getreues Ross' Zaumzeug des rachsüchtigen Streitrosses Zaumzeug des wachsamen Streitrosses Zaumzeug des goldenen Streitrosses\nVerkaufspreis:" }
entries[153175] = { ["name"] = "Zaumzeug des rachsüchtigen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGestattet es, dass beim Einsatz von 'Göttliches Ross' dieses zu Eurem rachsüchtigen Streitross wird. Exklusiv mit: Glyphe 'Getreues Ross' Zaumzeug des tapferen Streitrosses Zaumzeug des wachsamen Streitrosses Zaumzeug des goldenen Streitrosses\nVerkaufspreis:" }
entries[153176] = { ["name"] = "Zaumzeug des wachsamen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGestattet es, dass beim Einsatz von 'Göttliches Ross' dieses zu Eurem wachsamen Streitross wird. Exklusiv mit: Glyphe 'Getreues Ross' Zaumzeug des tapferen Streitrosses Zaumzeug des rachsüchtigen Streitrosses Zaumzeug des goldenen Streitrosses\nVerkaufspreis:" }
entries[153177] = { ["name"] = "Zaumzeug des goldenen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGestattet es, dass beim Einsatz von 'Göttlichen Ross' dieses zu Eurem goldenen Streitross wird. Exklusiv mit: Glyphe 'Getreues Ross' Zaumzeug des tapferen Streitrosses Zaumzeug des rachsüchtigen Streitrosses Zaumzeug des wachsamen Streitrosses\nVerkaufspreis:" }
entries[153178] = { ["name"] = "Einäscherungsfackel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Äschert geschändete Leichen sofort ein und befreit so ihre Geister." }
entries[153179] = { ["name"] = "Blaue Konservatoriumsschriftrolle", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine blaue Rune der Kraft über Euren Kopf. (1 Stunde Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\"Einst Teil von Archimondes Lehrplan am Arkankonservatorium.\"" }
entries[153180] = { ["name"] = "Gelbe Konservatoriumsschriftrolle", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine gelbe Rune der Kraft über Euren Kopf. (15 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\"Einst Teil von Archimondes Lehrplan am Arkankonservatorium.\"" }
entries[153181] = { ["name"] = "Rote Konservatoriumsschriftrolle", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine rote Rune der Kraft über Euren Kopf. (15 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\"Einst Teil von Archimondes Lehrplan am Arkankonservatorium.\"" }
entries[153182] = { ["name"] = "Heilige Lichtsphäre", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Wirft die Kugel einem freundlich gesinnten Spielercharakter zu. Wenn möglich, wird er sie automatisch zurückwerfen.\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:" }
entries[153183] = { ["name"] = "Barrierengenerator", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erzeugt eine temporäre Barriere. (1 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\"Die Kristalltechnologie zur Erzeugung dieser Barrieren ist immer noch nicht vollständig erforscht.\"\nVerkaufspreis:" }
entries[153184] = { ["name"] = "Glänzendes Medaillon", ["text"] = "Questgegenstand\n\"Das wird Jette die Klinge sicher zurückhaben wollen.\"" }
entries[153185] = { ["name"] = "Stählerne Vesperdose", ["text"] = "Questgegenstand\n\"Nach dem Wegwischen des Drecks erkennt man die polierte Oberfläche und gut geölte Scharniere. Bevor sie verloren gegangen ist, hat jemand sie in makellosem Zustand gehalten.\"" }
entries[153186] = { ["name"] = "Silberner Kompass", ["text"] = "Questgegenstand\n\"Auch wenn er mit Salz und Sand verkrustet ist, zeigt er noch tadellos die Richtung an.\"" }
entries[153187] = { ["name"] = "Zinnroboter", ["text"] = "Questgegenstand\n\"Wenn man den kleinen Schlüssel an der Rückseite dreht, beginnen seine Füße, wild zu tanzen.\"" }
entries[153188] = { ["name"] = "Großer gesegneter Verband", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Legt den Verband an, um 30 Min. lang alle 3 Sek. 5% Gesundheit wiederherzustellen und Angreifern Heiligschaden zuzufügen. Kann nur auf den Verheerten Inseln und Argus verwendet werden. (1s Abklingzeit) (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[153189] = { ["name"] = "Zerschmettertes Lichtschwert", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Bittet demütig, dass ein aufgestiegener Verteidiger nach Azeroth zurückkehrt, um 10 Min. lang an Eurer Seite zu kämpfen. Kann nur auf den Verheerten Inseln und Argus eingesetzt werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[153190] = { ["name"] = "Teufelsgeflecktes Ei", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 tagen (Realzeit)\n\"Aus diesem Ei wird etwas schlüpfen.\"\nVerkaufspreis:" }
entries[153191] = { ["name"] = "Gesprungenes teufelsgeflecktes Ei", ["text"] = "Wird beim Aufheben gebunden\n\"Aus diesem Ei ist etwas geschlüpft!\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[153192] = { ["name"] = "Sonnenglut", ["text"] = "Benutzen: Ein leicht leuchtendes Getränk. (Procchance: 20%, 15s Abklingzeit)\n\"Beliebt bei der Armee des Lichts, um die Moral zu stärken.\"\nVerkaufspreis:" }
entries[153193] = { ["name"] = "Baarut der Blitz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nReittier\n(Accountweit)\nBenutzen: Beschwört auf Argus einen reitbaren spektralen Talbuk. Das ist ein sehr, SEHR schnelles Reittier. (20 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:" }
entries[153194] = { ["name"] = "Kommunikationskugel der Legion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit, dort Signalfeuer zu beschwören, die die Streitkräfte der Legion anziehen. (10 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar." }
entries[153195] = { ["name"] = "Uunas Puppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Uuna beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar." }
entries[153197] = { ["name"] = "Segen des Standhaften", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verzaubert eine Schulterrüstung dauerhaft mit 'Standhaft', sodass sie es dem Träger gestattet, von den Leichen seiner Gegner Argunitformationen zu plündern. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Der Argusvorstoß\n- Respektvoll\nVerkaufspreis:" }
