entries[153203] = { ["name"] = "Uralte Angelschnur", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ersetzt die Angelschnur Eurer Angelrute mit einer uralten Schnur von Argus und erhöht die Angelfertigkeit um 6.\nBenötigt Angeln (1)\n\"Eine Schnur, die einen zehntausend Jahre langen Krieg übersteht, ist eine gute Schnur.\"" }
