entries[153247] = { ["name"] = "Segen des Lichtjüngers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verzaubert eine Schulterrüstung dauerhaft mit 'Lichtbringer', sodass sie es dem Träger gestattet, von den Leichen seiner Gegner Gunst des Lichts zu plündern. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Armee des Lichts\n- Respektvoll\nVerkaufspreis:" }
