entries[153249] = { ["name"] = "Y'meras Einstimmungskristall", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stimmt den Kristall auf die Essenz des Geistes ein. Das Ergebnis ist potenziell unvorhersehbar. (3 Sek. Abklingzeit)" }
