entries[153485] = { ["name"] = "Dunkelmond-Minizeppelin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nMit Rechtsklick Euren Dunkelmond-Minizeppelin beschwören oder wieder freigeben. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Silas hatte erwägt, seine Zeppelinflotte für Vermarktungszwecke einzusetzen, entschied dann aber, dass es die beste Form von Werbung wäre, sie einfach direkt an den Mann zu bringen.\"\nVerkäufer:\nLhara\nZone:\nDunkelmond-Insel\nKosten:\n1000" }
entries[153486] = { ["name"] = "Intakter Giftdorn", ["text"] = "Questgegenstand\n\"Wird an Harpunen der Sturmtakler befestigt, um große Tiere zu betäuben.\"" }
entries[153487] = { ["name"] = "Organische Diskombobulierungsgranate", ["text"] = "Benutzen: Wirft eine Bombe, die bei ihrer Detonation 5 mechanische Schafe beschwört. Gegner, die mit den Schafen in Kontakt kommen, werden für 20 Sek. verwandelt. Funktioniert nicht bei Zielen über Stufe 50. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[153490] = { ["name"] = "B.R.U.T.Z.L.", ["text"] = "Benutzen: Fügt allen Gegnern in einem Radius von 5 Metern 4180 Feuerschaden zu. (5 Min Abklingzeit)\n\"Blitz-Röstungs-Ultra-Thermo-Zünd-Lader. Explizit NICHT für Kochzwecke geeignet!\"\nVerkaufspreis:" }
entries[153493] = { ["name"] = "Sturmdrache des dämonischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Sturmdrachen des dämonischen Gladiators beschwört.\nSturmdrache des dämonischen Gladiators : Beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese schuppenbewehrte Sturmbestie aus den Bergen von Sturmheim setzt auf der Jagd nach ihrer Beute den Himmel in Flammen.\"\nErfolg:\nGladiator: Saison 7 von Legion\nKategorie:\nSpieler gegen Spieler" }
entries[153494] = { ["name"] = "Thermobeschleunigter Seuchenverbreiter", ["text"] = "Benutzen: Erzeugt einen vergifteten Bereich, der allen Gegnern alle 3 Sek. 1003 Schaden zufügt, solange sie sich darin aufhalten. Hält 15 Sek. lang an. (5 Min Abklingzeit)" }
entries[153496] = { ["name"] = "Schmackhafte Leckerbissen", ["text"] = "Questgegenstand\nBenutzen: Verfüttert einem von Meerahs Alpakas einen schmackhaften Leckerbissen." }
entries[153499] = { ["name"] = "Ferrinys Raketenrucksack", ["text"] = "Questgegenstand\n\"Benutzt ihn, um (vollkommen gefahrlos) losdüsen zu können!\"" }
entries[153501] = { ["name"] = "Truhe mit antorischen Schätzen", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[153502] = { ["name"] = "Truhe mit antorischen Schätzen", ["text"] = "Schlachtzugsbrowser\nWird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
