entries[153504] = { ["name"] = "Truhe mit antorischen Schätzen", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[153505] = { ["name"] = "Monelitschießeisen", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n8 - 13 Schaden Geschwindigkeit 3.00\n(3.5 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n+ 5 Vielseitigkeit\nVerkaufspreis:" }
entries[153506] = { ["name"] = "Präzise abgestimmter Sturmstahlvernichter", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n14 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[153507] = { ["name"] = "Hundertjähriger Bourbon", ["text"] = "Questgegenstand" }
entries[153508] = { ["name"] = "Gezeitenperle der Stürme", ["text"] = "Questgegenstand\nEinzigartig (3)" }
entries[153509] = { ["name"] = "Hut der Eisenfluträuber", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verkleidet Euch als Mitglied der Eisenfluträuber.\n\"Ein Großteil des Blutes wurde herausgewaschen.\"" }
entries[153510] = { ["name"] = "Interdimensionales Begleiterrepositorium", ["text"] = "Benutzen: Beschwört einen tragbaren Stallmeister, mit dem Jäger bis zu 2 Min. lang interagieren können.\nVerkaufspreis:" }
entries[153512] = { ["name"] = "XA-1000 Wellengleiter", ["text"] = "Benutzen: Setzt ein Boot ein, das sofort losfährt und sich 25 Sek. lang über das Wasser bewegt. Funktioniert nicht an Land. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[153513] = { ["name"] = "Reinigendes Tonikum", ["text"] = "Questgegenstand\nBenutzen: Verabreicht dem Ziel Therolds Tonikum, wodurch sich sein Magen entleert." }
entries[153514] = { ["name"] = "Hanzabus Glücksbringer", ["text"] = "Questgegenstand\n\"Jedes Mal, wenn Ihr ihn anseht, habt Ihr das Gefühl, jemand würde an Euch zerren. Also ob er versuchen würde, Euch näher heranzuziehen.\"" }
entries[153515] = { ["name"] = "Nagaspeerspitze", ["text"] = "Questgegenstand\nEinzigartig\n\"Die abgenutzte Speerspitze einer Nagawaffe.\"" }
entries[153516] = { ["name"] = "Schriftrolle der Gezeitenperlenkanalisierung", ["text"] = "Zuldazar\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[153517] = { ["name"] = "Koloas Monokel", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf dem Rahmen ist ein 'K' eingraviert.\"" }
entries[153519] = { ["name"] = "Himmelsruferedelstein", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Edelstein enthält neben unglaublichen Blitzenergien auch noch Ingrids ganz eigene Form von Schattenmagie.\"" }
entries[153520] = { ["name"] = "Primordiumsplitter", ["text"] = "Questgegenstand\n\"Ein seltener Kristall, der durch die plötzliche Freisetzung von gewaltigen Energiemengen entstanden ist.\"" }
entries[153521] = { ["name"] = "Kristallisiertes Herz", ["text"] = "Questgegenstand\n\"Das kristallisierte Herz eines Glasschwanzskorpidopfers.\"" }
entries[153524] = { ["name"] = "Schädelpfeife der Rastari", ["text"] = "Questgegenstand\nBenutzen: Stößt einen unheimlichen Kriegsschrei aus, der Verteidiger der Rastari innerhalb von 25 Metern ermutigt." }
entries[153525] = { ["name"] = "Zurückgeholter Schmuck", ["text"] = "Questgegenstand" }
entries[153526] = { ["name"] = "Zauberfoliant der Anderen Seite", ["text"] = "Questgegenstand" }
entries[153527] = { ["name"] = "Verehrte Überreste", ["text"] = "Questgegenstand" }
entries[153529] = { ["name"] = "Verdichteter Donner", ["text"] = "Questgegenstand" }
entries[153536] = { ["name"] = "Zothix' Kopf", ["text"] = "Questgegenstand\n\"Der abgeschlagene Kopf eines Sethrakkriegsfürsten.\"" }
entries[153537] = { ["name"] = "Belebte Sphäre", ["text"] = "Questgegenstand\nBenutzen: Auf einen uralten Steingolem anwenden, um ihn zum Leben zu erwecken.\n\"Die goldene Aura der uralten Kugel pulsiert.\"" }
entries[153538] = { ["name"] = "Sturmessenz", ["text"] = "Questgegenstand\n\"Ein Funken lebendigen Sturms.\"" }
entries[153539] = { ["name"] = "Seefester Hengst", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren seefesten Hengst oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Im Militär von Kul Tiras wird den Pferden schon früh antrainiert, das Meer nicht zu fürchten, sondern sich daran zu erfreuen, entlang der Küste und durch die Gischt zu galoppieren.\"\nPromotion:\nBattle for Azeroth Collector's Edition" }
entries[153540] = { ["name"] = "Goldbesetzter Ravasaurus", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren goldbesetzten Ravasaurus oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Reittier wäre eines Hohepriesters oder Ratsmitglieds der Zandalari würdig, mit seinen Verzierungen aus feinstem Gold und gesegnet von Rezan, dem großen Teufelssaurierloa.\"\nPromotion:\nBattle for Azeroth Collector's Edition" }
entries[153541] = { ["name"] = "Törtel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Törtel beschwören oder wieder freigeben.\n80 ( 80)" }
entries[153543] = { ["name"] = "Eisenerz", ["text"] = "Das Arathihochland\n\"Kann bei der Eisenmine abgegeben und zu Eisen verarbeitet werden. Wird zum Bau von Gebäuden an der Kriegsfront verwenden.\"" }
entries[153544] = { ["name"] = "Auge von F'harg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Augen der Hunde (1)\nSchmuck\n+5 [Beweglichkeit oder Stärke]\n43 Rüstung\nAnlegen: Gewährt einem Verbündeten mit Tankspezialisierung in der Nähe, der das Auge von Shatug trägt, zusätzlich 2 Vielseitigkeit.\nBenutzen: Verwandelt in das Auge von Shatug. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[153545] = { ["name"] = "Holz", ["text"] = "Das Arathihochland" }
entries[153546] = { ["name"] = "Sethrakrelikt", ["text"] = "Questgegenstand\n\"Vorsichtig behandeln... sehr vorsichtig.\"" }
entries[153553] = { ["name"] = "Stein der Visionen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört eine Elementarvision von Zalizi der Wanderin. (5 Sek. Abklingzeit)" }
entries[153554] = { ["name"] = "Herz von Sethraliss", ["text"] = "Questgegenstand\n\"Eine Sphäre aus gefärbtem Glas, die sich glatt und kühl anfühlt.\"" }
entries[153555] = { ["name"] = "Alor'idalkristall", ["text"] = "Questgegenstand\n\"Dieser Kristall vibriert vor Magie. Illidan hat Euch gebeten, sich seiner anzunehmen.\"" }
entries[153556] = { ["name"] = "Sethrakwaffe", ["text"] = "Questgegenstand\n\"Gefertigt aus Glas und anderen Materialien, die man nur in Vol'dun findet.\"" }
entries[153557] = { ["name"] = "Fesselndes Totem", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt das Nullifikationstotem auf dem Boden auf. Kann nur in Atul'Aman verwendet werden. (5 Sek. Abklingzeit)" }
entries[153558] = { ["name"] = "Kristallisiertes Herz", ["text"] = "Questgegenstand\n\"Das kristallisierte Herz eines Glasschwanzskorpidopfers.\"" }
entries[153565] = { ["name"] = "Fesseln", ["text"] = "Questgegenstand\nBenutzen: Fesselt Euer Ziel, wenn es über weniger als 50% Gesundheit verfügt.\n\nKann nur gegen Sethrak innerhalb des Tempelübergriffs verwendet werden." }
entries[153566] = { ["name"] = "\"Glitzernder\" Stein", ["text"] = "\"Der hier schön. Schön nutzlos! HAH! Nicht zu viel zu gebrauchen.\"\nVerkaufspreis:" }
entries[153567] = { ["name"] = "\"Polierter\" Stein", ["text"] = "\"Spiegelt so, dass Ihr Hut sehen könnt, den Ihr von Scha'poh gekauft habt. Bin guter Querverkaufsoger.\"\nVerkaufspreis:" }
entries[153568] = { ["name"] = "\"Fliegender\" Stein", ["text"] = "\"Ich kleinen Gnom treffen, der ihn 'bäro-dünna-misch' genannt, der Name aber dumm. Kommt nicht gut an bei Steinkäufern. Der gut zum Werfen.\"\nVerkaufspreis:" }
entries[153569] = { ["name"] = "\"Harter\" Stein", ["text"] = "\"Der Verkaufsschlager! Weil der sein am besten zum Schlagen. Für zu Hause, die Arbeit und überhaupt alles!\"\nVerkaufspreis:" }
entries[153570] = { ["name"] = "\"Magischer\" Stein", ["text"] = "\"Der hier besonders magisch. Mein Häuptling mir das sagen. Magie versprochen, sonst Geld zurück!\"\nVerkaufspreis:" }
entries[153571] = { ["name"] = "Vergifteter Blaspfeil", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verringert die maximale Gesundheit eines Kriegsreiters der Blutjäger um 90% und seinen Schaden um 50%." }
entries[153572] = { ["name"] = "Naglas Kopf", ["text"] = "Questgegenstand\n\"Der abgetrennte Kopf von Kriegsmatrone Nagla.\"" }
entries[153573] = { ["name"] = "Elektroschocker zur Reittiermotivierung", ["text"] = "Benutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\nNicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"\nVerkaufspreis:" }
entries[153574] = { ["name"] = "Gewöhnliche Hutschachtel", ["text"] = "\"Eine Doppelhutschachtel.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[153576] = { ["name"] = "Kobas Spielzeugzug", ["text"] = "Questgegenstand\n\"Er ist deutlich langsamer als die meisten Züge.\"" }
entries[153577] = { ["name"] = "Plüschgonk", ["text"] = "Questgegenstand\n\"Nicht in Lebensgröße.\"" }
entries[153578] = { ["name"] = "Plüschelekk", ["text"] = "Questgegenstand\n\"Ein Souvenir aus einem fernen Land.\"" }
entries[153579] = { ["name"] = "Herz von Sethraliss", ["text"] = "Questgegenstand\n\"Eine Sphäre aus gefärbtem Glas, die sich glatt und kühl anfühlt.\"" }
entries[153580] = { ["name"] = "Gezeitenperle der Winde", ["text"] = "Questgegenstand\nEinzigartig (3)" }
entries[153581] = { ["name"] = "Gezeitenperle der Ströme", ["text"] = "Questgegenstand\nEinzigartig (3)" }
entries[153591] = { ["name"] = "Gürtelverzauberung: Schreckenshologrammprojektor", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden." }
entries[153592] = { ["name"] = "Gürtelverzauberung: Ellbogenfreiheit", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr Euer aktuelles Ziel zurückstoßen könnt. Teilt sich die Abklingzeit mit Tränken.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden." }
entries[153593] = { ["name"] = "Riesiger Rippenknochen von Blutkrone", ["text"] = "Questgegenstand" }
entries[153594] = { ["name"] = "Xiwyllag-Flugfahrboot", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man das Xiwyllag-Flugfahrboot fährt.\nBeschwört Euer Xiwyllag-Flugfahrboot oder gibt es wieder frei. Dieses Fahrzeug passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Man sagt, dass diese Erfindung dem Aussehen eines sehr reichen Goblins nachempfunden wurde. Andere sehen allerdings keine Ähnlichkeit.\"\nBeruf:\nSchmiedekunst & Ingenieurskunst" }
entries[153595] = { ["name"] = "Klebriger Bienenhonig", ["text"] = "Questgegenstand" }
entries[153596] = { ["name"] = "Ziegenschere", ["text"] = "Questgegenstand\nBenutzen: Rasiert eine Ziege mit nur \"minimalen\" Ritzern und Schrammen! (5 Sek. Abklingzeit)" }
entries[153597] = { ["name"] = "Stationärer Umkleider", ["text"] = "Benutzen: Beschwört ein Gerät, mit dem Ihr das Aussehen Eurer Rüstung verändern könnt. Das Gerät bleibt bis zu 2 Min. lang bestehen.\n\"Hinweis: Aufgrund der Funktionsweise dieses Geräts sind leichte Kopfschmerzen, Übelkeit sowie Wechsel von Volkszugehörigkeit und/oder Geschlecht nicht auszuschließen. Mit Vorsicht zu verwenden.\"\nVerkaufspreis:" }
entries[153598] = { ["name"] = "Dunkelmond-Karte des Krieges", ["text"] = "\"Irgendeine Dunkelmond-Karte des Krieges. Sammelt das ganze Set, um eine Belohnung zu erhalten.\"" }
entries[153599] = { ["name"] = "Des Toten letzter Krug", ["text"] = "Questgegenstand\nBenutzen: Trinkt mich.\n\"Kleine Bläschen dringen wie Fäden an die Oberfläche, bevor sie sich zu zartem Schaum sammeln.\"" }
entries[153600] = { ["name"] = "Ziegenmilch", ["text"] = "Questgegenstand\nBenutzen: Trinkt mich.\n\"Gut für die Knochen! Nur nicht fürs Holzbein.\"" }
entries[153601] = { ["name"] = "Ziegenmilch im Schädelbecher", ["text"] = "Questgegenstand\nBenutzen: Trinkt mich.\n\"Wenn man Milch trinken und dennoch hart aussehen will.\"" }
entries[153602] = { ["name"] = "Ritualskorpidenblut", ["text"] = "Benutzen: Erlebt erneut Eure Aufnahme in die Goldhauerbande.\nVerkaufspreis:" }
