entries[153673] = { ["name"] = "Vantusrune: Uldir", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Uldir ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
